import styled from '@emotion/styled';

export const StyledEmbeddedBigNumbersWrapper = styled.div({
  position: 'relative',
  zIndex: 0,
  isolation: 'isolate',
});

export const StyledBigNumbersContainer = styled.div({
  display: 'grid',
  gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
  gap: '16px',
  width: '100%',
  alignItems: 'stretch',

  '& .performance-tool-big-number': {
    height: '100%',
  },

  '& .performance-tool-big-number .bigNumberContainer': {
    display: 'flex',
    flexDirection: 'column',
    height: '100%',
  },

  '& .performance-tool-big-number .bigNumberContainer > div:nth-child(2)': {
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    minHeight: 0,
  },

  '& .performance-tool-big-number .bigNumberContainer > div:nth-child(2) > div:first-child':
    {
      flex: 1,
      display: 'flex',
      flexDirection: 'column',
      minHeight: 0,
    },

  '& .performance-tool-big-number .bigNumberContainer > div:nth-child(2) > div:first-child > div:first-child':
    {
      flex: 1,
      display: 'flex',
      alignItems: 'center',
      width: '100%',
    },

  '& .performance-tool-big-number .bigNumberContainer > div:nth-child(2) > div:first-child > div:last-child:not(:first-child)':
    {
      flexShrink: 0,
      paddingTop: '8px',
    },

  '& .performance-tool-big-number p + span': {
    fontSize: '12px !important',
    lineHeight: '12px !important',
  },
});

export const StyledBigNumberFooter = styled.div({
  display: 'flex',
  alignItems: 'center',
  fontFamily: 'Work Sans',
  color: '#5C5C5C',
  justifyContent: 'center',
  padding: '12px 0 0 0',
  gap: '4px',

  p: {
    fontSize: '16px',
    fontWeight: '500',
    margin: 0,
  },
  span: {
    fontSize: '12px',
    fontWeight: '400',
  },
});
